/*
 * A054073  Fractal sequence induced by sqrt(2): for k >= 1 let p(k) be the
 *          permutation of 1,2,...,k obtained by ordering the fractional parts
 *          {h*sqrt(2)} for h=1,2,...,k; then juxtapose p(1),p(2),p(3),...
 * https://oeis.org/A054073
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth element in the concatenation of the permutations
 *            p(k) (k = 1,2,…) obtained by ordering the fractional parts
 *            {h*sqrt(2)} for h = 1,…,k. The sequence is generated by
 *            computing the permutation for the appropriate k on each call
 * Range:     u8 n <= 86, u16 n <= 86, u32 n <= 86, u64 n <= 86, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function meets the constraints in the problem statement. */
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

/* Item used when sorting by fractional part */
struct Item {
    uint64_t val;
    long double frac;
};

seq_t a(idx_t n)
{
    /* sequences are 1-indexed; n >= 1 is guaranteed by the caller */
    /* locate the block k such that T(k-1) < n <= T(k)  */
    idx_t k = (idx_t)((sqrtl(8.0L * n + 1.0L) - 1.0L) / 2.0L);
    if (((k * (k + 1)) / 2) < n) ++k;                 /* ensure ceil */
    idx_t prev_tri = ((k - 1) * k) / 2;
    idx_t pos = n - prev_tri - 1;                     /* 0‑based inside p(k) */

    /* For k = 1 simply return 1. */
    if (k == 1)
        return (seq_t)1;

    /* Allocate an array of Items, one per h=1…k. */
    struct Item *items = (struct Item *)malloc(k * sizeof(struct Item));
    if (!items) return (seq_t)0;      /* memory failure – unlikely in test */

    static const long double SQRT2 = sqrtl(2.0L);

    /* Fill items with value and fractional part of h*sqrt(2). */
    for (idx_t i = 0; i < k; ++i) {
        uint64_t h = i + 1;
        long double x = h * SQRT2;
        items[i].val  = h;
        items[i].frac = x - floorl(x);
    }

    /* Sort items by fractional part.  Insertion sort is fine for k <= ~100 */
    for (idx_t i = 1; i < k; ++i) {
        struct Item key = items[i];
        idx_t j = i;
        while (j > 0 && items[j - 1].frac > key.frac) {
            items[j] = items[j - 1];
            --j;
        }
        items[j] = key;
    }

    /* Retrieve the element at the required position. */
    seq_t result = (seq_t)items[pos].val;

    /* Clean up. */
    free(items);

    return result;
}
